export function sealForRecipient(recipientPublicKeyPem: string, plaintext: Buffer): ShareToken {
  const oneTimeKey = randomBytes(32); // AES-256, fresh every time
  const blob = encrypt(oneTimeKey, plaintext); // AES-256-GCM, no payload-size limit
  const wrappedKey = publicEncrypt({ key: recipientPublicKeyPem, ...RSA_OPTIONS }, oneTimeKey); // RSA-OAEP wraps only the 32-byte key
  return { wrappedKey: wrappedKey.toString("base64"), blob };
}

